import { useEffect, useRef } from 'react'
import { SceneRoom, type SceneRoomOccupant, type SceneRoomOptions } from '@nexus/character-kit'

export type SceneRoomCanvasProps = {
  occupants: SceneRoomOccupant[]
  gestureManifestUrl?: string
  className?: string
  style?: React.CSSProperties
  roomOptions?: Omit<SceneRoomOptions, 'logger'>
  onRoomReady?: (room: SceneRoom | null) => void
}

export function SceneRoomCanvas({
  occupants,
  gestureManifestUrl,
  className,
  style,
  roomOptions,
  onRoomReady,
}: SceneRoomCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const roomRef = useRef<SceneRoom | null>(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const room = new SceneRoom(canvas, {
      orbitControls: true,
      pointerLook: true,
      background: 0x12171c,
      gestureManifestUrl,
      ...roomOptions,
    })
    roomRef.current = room
    onRoomReady?.(room)
    return () => {
      room.dispose()
      roomRef.current = null
      onRoomReady?.(null)
    }
  }, [gestureManifestUrl, roomOptions, onRoomReady])

  useEffect(() => {
    const room = roomRef.current
    if (!room) return
    void room.setOccupants(occupants)
  }, [occupants])

  const canvasStyle: React.CSSProperties = {
    width: '100%',
    height: 480,
    display: 'block',
    ...style,
  }

  return <canvas ref={canvasRef} className={className} style={canvasStyle} aria-label="3D scene room" />
}
